import{_ as r,C as i,o as h,c as o,a3 as n,E as l,j as e,a as d}from"./chunks/framework.Ba39LDvt.js";const D=JSON.parse('{"title":"EDA 算法自学","description":"用图算法、优化、开源实现和竞赛评测学习 EDA，并建立 AI4EDA 实验的正确边界。","frontmatter":{"title":"EDA 算法自学","description":"用图算法、优化、开源实现和竞赛评测学习 EDA，并建立 AI4EDA 实验的正确边界。"},"headers":[],"relativePath":"self-learning/eda-algo.md","filePath":"self-learning/eda-algo.md","lastUpdated":1795513256000}'),s={name:"self-learning/eda-algo.md"};function c(b,t,u,g,f,A){const a=i("CourseTable");return h(),o("div",null,[t[0]||(t[0]=n('<h1 id="eda-算法自学" tabindex="-1">EDA 算法自学 <a class="header-anchor" href="#eda-算法自学" aria-label="Permalink to &quot;EDA 算法自学&quot;">​</a></h1><p>电子设计自动化（Electronic Design Automation，EDA）不仅是调用软件命令，也包括把设计问题形式化为图、约束与优化目标。推荐路线是<strong>看懂设计流程 → 实现小算法 → 检查合法性 → 接入真实基准 → 比较质量和运行成本</strong>。工具使用入口见 <a href="/shanghaitech-ic-wiki-dev.github.io/eda/">EDA 全景</a>，方向路径见 <a href="/shanghaitech-ic-wiki-dev.github.io/map/eda">EDA 学习地图</a>。</p><h2 id="入门-补算法-也补电路语义" tabindex="-1">入门：补算法，也补电路语义 <a class="header-anchor" href="#入门-补算法-也补电路语义" aria-label="Permalink to &quot;入门：补算法，也补电路语义&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源</th><th>类型</th><th>难度</th><th>说明</th></tr></thead><tbody><tr><td>Cormen 等《Introduction to Algorithms》</td><td>算法教材</td><td>入门—进阶</td><td>优先学图遍历、最短路、最小生成树、动态规划和复杂度</td></tr><tr><td>Sait、Youssef《VLSI Physical Design Automation: Theory and Practice》</td><td>EDA 教材</td><td>进阶</td><td>从划分、布局和布线认识典型物理设计问题</td></tr><tr><td>Kahng、Lienig、Markov、Hu《VLSI Physical Design: From Graph Partitioning to Timing Closure》</td><td>EDA 教材</td><td>进阶</td><td>连接算法与物理实现流程，适合建立问题全景</td></tr><tr><td>De Micheli《Synthesis and Optimization of Digital Circuits》</td><td>逻辑综合教材</td><td>进阶</td><td>理解布尔表示、逻辑优化与技术映射，而不只关注物理设计</td></tr><tr><td><a href="https://www.cse.cuhk.edu.hk/~byu/" target="_blank" rel="noreferrer">Bei Yu 公开主页</a></td><td>教学与研究入口</td><td>进阶</td><td>从 Teaching、研究主题和公开材料进入 EDA 与机器学习；不假定所有课程视频都开放</td></tr></tbody></table><p>做算法前先明确输入：网表是图还是超图？引脚方向是否影响定义？优化的是线长、时序还是拥塞？一个“线长更短”的非法布局不算改进，一次更快但漏掉约束的评测也不可比较。建议先画出十几个单元的小例子，再写数据结构。</p><h2 id="进阶-读开源实现与研究问题" tabindex="-1">进阶：读开源实现与研究问题 <a class="header-anchor" href="#进阶-读开源实现与研究问题" aria-label="Permalink to &quot;进阶：读开源实现与研究问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源</th><th>类型</th><th>难度</th><th>说明</th></tr></thead><tbody><tr><td><a href="https://theopenroadproject.org/" target="_blank" rel="noreferrer">OpenROAD</a></td><td>开源数字物理设计平台</td><td>进阶—深入</td><td>选择一个模块，如全局布局、合法化或布线，沿输入、算法与输出阅读</td></tr><tr><td><a href="https://github.com/berkeley-abc/abc" target="_blank" rel="noreferrer">ABC</a></td><td>逻辑综合与验证系统</td><td>进阶—深入</td><td>学习布尔网络、重写、技术映射及等价检查的基本思路</td></tr><tr><td><a href="https://github.com/limbo018/DREAMPlace" target="_blank" rel="noreferrer">DREAMPlace</a></td><td>可微布局研究实现</td><td>进阶—深入</td><td>理解将布局优化映射到深度学习框架的思路，不把“用了 GPU”直接等同于所有阶段更快</td></tr><tr><td><a href="https://ai4eda.github.io/" target="_blank" rel="noreferrer">AI × EDA 文献索引</a></td><td>研究导航</td><td>进阶</td><td>从问题类别找代表工作，再回到原论文、代码与数据定义</td></tr><tr><td><a href="https://www.iccad-contest.org/" target="_blank" rel="noreferrer">ICCAD CAD Contest</a></td><td>竞赛题目与评测</td><td>进阶—深入</td><td>选一个往届题，先读输入输出、限制和官方评分规则</td></tr><tr><td><a href="https://ispd.cc/" target="_blank" rel="noreferrer">ISPD</a></td><td>会议与竞赛入口</td><td>进阶—深入</td><td>查找物理设计问题与基准，具体资源按各届主页说明获取</td></tr></tbody></table><p>AI4EDA 可以从三类问题入手：预测时序、拥塞或功耗的代理模型；用可微优化、强化学习等方法搜索布局或设计参数；用学习方法辅助逻辑与电路生成。每类问题都要问：标签来自哪里、是否跨设计泛化、推理和数据生成成本是否计入、最终结果有没有经过真实工具验证。训练测试划分应避免同源设计或高度相似版本造成信息泄漏。</p><h2 id="实践-完成一个可判定对错的项目" tabindex="-1">实践：完成一个可判定对错的项目 <a class="header-anchor" href="#实践-完成一个可判定对错的项目" aria-label="Permalink to &quot;实践：完成一个可判定对错的项目&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源</th><th>类型</th><th>难度</th><th>说明</th></tr></thead><tbody><tr><td>时序图上的到达时间计算</td><td>图算法练习</td><td>入门—进阶</td><td>从有向无环图求拓扑序，计算路径延迟并与手算核对</td></tr><tr><td>小规模划分、布局或迷宫布线</td><td>算法项目</td><td>进阶</td><td>先有合法性检查器，再比较目标函数，保留简单基线</td></tr><tr><td>OpenROAD 单模块实验</td><td>工程项目</td><td>进阶—深入</td><td>固定设计、约束、库和随机种子，记录质量、时间与内存</td></tr><tr><td>往届 ICCAD / ISPD 题目复现</td><td>竞赛实践</td><td>深入</td><td>先跑通官方评测，再改算法；不要自行缩减约束或替换评分规则</td></tr></tbody></table><p>最合适的第一份报告通常很小：例如在同一批网表上比较两种划分策略。记录合法率、目标值、运行时间与峰值内存；失败样例也保留。若仅在玩具图上验证，就明确标注为教学实验，不宣称工业规模或先进工艺适用。更多论文与实验组织方法见 <a href="/shanghaitech-ic-wiki-dev.github.io/research-guide/">科研入门</a>。</p><h2 id="与上科大课程配合" tabindex="-1">与上科大课程配合 <a class="header-anchor" href="#与上科大课程配合" aria-label="Permalink to &quot;与上科大课程配合&quot;">​</a></h2>',12)),l(a,{codes:"EE215A,SI231B,SI251,SI365"}),t[1]||(t[1]=e("p",null,[d("EDA 算法需要数据结构、矩阵计算与优化共同支撑。可沿 EE215A 的课程方向选择主线，再按问题补数学和机器学习；实际课程内容以当学期大纲为准。学校的研究入口见 "),e("a",{href:"/shanghaitech-ic-wiki-dev.github.io/research/eda"},"EDA 研究方向"),d("，不要把公开资料的作者列表当作本校导师名单。")],-1)),t[2]||(t[2]=e("h2",{id:"参考与来源",tabindex:"-1"},[d("参考与来源 "),e("a",{class:"header-anchor",href:"#参考与来源","aria-label":'Permalink to "参考与来源"'},"​")],-1)),t[3]||(t[3]=e("ul",null,[e("li",null,[e("a",{href:"https://faculty.sist.shanghaitech.edu.cn/office/Academics/Courses/SIST_2026-2027_Courses.htm",target:"_blank",rel:"noreferrer"},"上科大信息学院 2026–2027 学年开课计划"),d("。")]),e("li",null,"开源项目、Bei Yu 教学与 ICCAD / ISPD 官方入口见上表；教材通过图书馆检索。")],-1))])}const m=r(s,[["render",c]]);export{D as __pageData,m as default};
